// Executa SQL com placeholders `?` + params. NECESSARIO porque o Drizzle
// db.execute() IGNORA o 2o argumento — entao db.execute("...?", [v]) nunca passava
// os valores (toda query assim falhava com "params: vazio"). Interpola com seguranca
// (numeros direto, strings escapadas) e retorna [rows, fields] no formato mysql2
// para manter compatibilidade com os desempacotamentos existentes (const [[x]] / const [x]).
async function execP(db: any, text: string, params: any[] = []): Promise<[any[], any[]]> {
  let i = 0;
  const finalSql = text.replace(/\?/g, () => {
    const p = params[i++];
    if (p === null || p === undefined) return "NULL";
    if (typeof p === "number") return String(p);
    if (typeof p === "boolean") return p ? "1" : "0";
    if (p instanceof Date) return "'" + p.toISOString().slice(0, 19).replace("T", " ") + "'";
    return "'" + String(p).replace(/\\/g, "\\\\").replace(/'/g, "''") + "'";
  });
  const r: any = await db.execute(drzSql.raw(finalSql));
  // r normalmente é [data, fields]. data pode ser:
  //  - array de rows (SELECT)
  //  - ResultSetHeader (INSERT/UPDATE/DELETE — objeto com {insertId, affectedRows, ...})
  // Para SELECT retornamos rows; para INSERT/UPDATE/DELETE retornamos o
  // ResultSetHeader (consumidores fazem `const [res] = ...; res.insertId`).
  let data: any = Array.isArray(r) ? r[0] : r;
  if (data === undefined) data = [];
  return [data, []];
}

const ACTIVE_EMPLOYEE_ROLES = ["user", "chefia", "cipa", "sesmt", "admin", "company_admin"] as const;

function activeEmployeeWhere(alias = "u"): string {
  return `${alias}.is_active=1 AND COALESCE(${alias}.employment_status,'active')='active' AND ${alias}.role IN (${ACTIVE_EMPLOYEE_ROLES.map((r) => `'${r}'`).join(",")})`;
}

function firstDbRow(result: any): any | null {
  const rows = Array.isArray(result) ? result[0] : result;
  if (Array.isArray(rows)) return rows[0] ?? null;
  return rows ?? null;
}

const ISO_COURSE_ACCESS_ROLES = new Set(["admin", "company_admin", "rh", "sesmt", "admin_global", "super_admin"]);

async function assertCourseAccessForUser(db: any, user: any, moduleId: number) {
  const mr: any = await db.execute(drzSql`
    SELECT id, title, description, image_url, durationMinutes, template_category
    FROM modules
    WHERE id=${moduleId} AND isActive=1
    LIMIT 1
  `);
  const mod = firstDbRow(mr);
  if (!mod) throw new TRPCError({ code: "NOT_FOUND" });
  const category = String(mod.template_category ?? "").toLowerCase();
  const role = String(user?.role ?? "");
  if (category === "iso" && !ISO_COURSE_ACCESS_ROLES.has(role)) {
    throw new TRPCError({ code: "FORBIDDEN", message: "Curso restrito aos perfis Admin, RH e SESMT." });
  }
  return mod;
}

